    # c2 is gold; the order summary applies a discount, and the history must match it.
    placed = order(shop, "c2", ("LAMP", 1), ("BOOK", 4)).body["order_id"]
    summary = shop.orders.handle_get(placed).body
    assert summary["discount_cents"] > 0

    history = shop.insights.handle_order_history("c2").body["orders"]

    assert history == [{"order_id": placed, "status": "placed", "total_cents": summary["total_cents"]}]


def test_other_customers_orders_are_excluded(shop):
    order(shop, "c1", ("BOOK", 1))
    mine = order(shop, "c2", ("PEN", 1)).body["order_id"]

    orders = shop.insights.handle_order_history("c2").body["orders"]

    assert [o["order_id"] for o in orders] == [mine]

