class CustomerInsightsController:
    def __init__(self, orders: OrderService, customers: CustomerService) -> None:
        self._orders = orders
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with the same totals as the order summary."""
        try:
            summaries = self._orders.summaries_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        orders: list[dict[str, Any]] = [
            {"order_id": s.order.order_id, "status": s.order.status, "total_cents": s.total_cents}
            for s in summaries
        ]
        return Response(200, {"customer_id": customer_id, "orders": orders})

