        """(number of non-cancelled orders, sum of their totals). Raises CustomerNotFound."""
        summaries = self._orders.summaries_for_customer(customer_id)
        active = [s for s in summaries if s.order.status != "cancelled"]
        return len(active), sum(s.total_cents for s in active)

